-- ITパスポート試験
INSERT INTO entities (type, slug, name, category, attributes, official_stats)
VALUES ('certification', 'it-passport', 'ITパスポート試験', 'IT・情報', '{"short_name":"ITパスポート","authority":{"name":"独立行政法人 情報処理推進機構(IPA)","url":"https://www.ipa.go.jp/shiken/kubun/ip.html"},"exam":{"eligibility":"受験資格の制限なし。公式FAQに「受験資格は特段ありません」と明記されており、年齢・学歴は問われない。","fee_yen":7500,"format":"CBT(コンピュータを使った試験)。多肢選択式(四肢択一)の小問が100問出題される。出題分野はストラテジ系(経営全般)・マネジメント系(IT管理)・テクノロジ系(IT技術)の3つ。","questions":100,"duration_minutes":120,"passing_criteria":"総合評価点が1,000点満点中600点以上であること。加えて、ストラテジ系・マネジメント系・テクノロジ系の分野別評価点がそれぞれ1,000点満点中300点以上であること。総合点が600点を超えていても、1分野でも300点を下回ると不合格になる。","frequency":"CBT方式で年間を通じて随時実施される。全国の試験会場から日程を選んで申し込む。","result_announcement":"受験した月の翌月下旬に、サイトへ受験番号が掲載される(例: 5月に受験した場合は6月22日正午に発表予定)。合格者の受験番号は官報にも公示され、合格証書は発表の翌月に簡易書留で郵送される。","source_urls":{"eligibility":"https://www3.jitec.ipa.go.jp/JitesCbt/html/reference/faq.html","fee_yen":"https://www.ipa.go.jp/shiken/mousikomi/schedule.html","format":"https://www.ipa.go.jp/shiken/kubun/ip.html","questions":"https://www.ipa.go.jp/shiken/kubun/ip.html","duration_minutes":"https://www.ipa.go.jp/shiken/kubun/ip.html","passing_criteria":"https://www3.jitec.ipa.go.jp/JitesCbt/html/about/range.html","subjects":"https://www3.jitec.ipa.go.jp/JitesCbt/html/about/range.html","frequency":"https://www.ipa.go.jp/shiken/mousikomi/schedule.html","result_announcement":"https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/pass.html"},"subjects":["ストラテジ系 35問程度","マネジメント系 20問程度","テクノロジ系 45問程度"],"fee_note":"2022年4月実施の試験から、5,700円が7,500円に改定された。","retrieved_at":"2026-07-26"},"related":[{"slug":"boki-3kyu","reason":"同じく受験資格の制限がなく、通年のCBTで受けられる入門級の資格"}],"schedule_url":"https://www.ipa.go.jp/shiken/mousikomi/schedule.html","verification":{"collected_by":"researcher(一次ソースのみ)+ PM(Fable)","verified_by":"未実施","verified_at":null,"result":"🔴 独立検証が未実施。統計5年度分は合格者数÷受験者数の検算を全件通している。未検証の中心は (1) 分野別の出題数(「程度」とされ固定ではない) (2) 合格発表の時期を個別月の例から一般化して記述している点。"},"notes":"確認できなかった項目: (1) 試験日から合格発表日までの日数を定めた一般ルール。公式には個別月の発表日(翌月22日前後)が示されるのみで、「何日後」という明文の規定を見つけられなかった。(2) 受験手数料をITパスポート単独で「税込」と明記した文。情報処理技術者試験全体について消費税込みとする記述はある。いずれも推測で埋めていない。","public_note":"合格には、総合点だけでなく3分野それぞれで300点以上を取る必要があります。総合点が合格ラインを超えていても、1分野でも下回ると不合格になります。"}', '{"official_stats":{"unit":"全国集計(年度単位・IPA発表)","series":[{"year":"令和7年度","applicants":307266,"examinees":271352,"passers":132012,"pass_rate":48.6,"source_url":"https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/pdf/statistics/202603_ip_shikenkekka.pdf","retrieved_at":"2026-07-26"},{"year":"令和6年度","applicants":309068,"examinees":273905,"passers":134617,"pass_rate":49.1,"source_url":"https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/pdf/statistics/202503_ip_shikenkekka.pdf","retrieved_at":"2026-07-26"},{"year":"令和5年度","applicants":297864,"examinees":265040,"passers":133292,"pass_rate":50.3,"source_url":"https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/pdf/statistics/202403_ip_shikenkekka.pdf","retrieved_at":"2026-07-26"},{"year":"令和4年度","applicants":253159,"examinees":231526,"passers":119495,"pass_rate":51.6,"source_url":"https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/pdf/statistics/202303_ip_shikenkekka.pdf","retrieved_at":"2026-07-26"},{"year":"令和3年度","applicants":244254,"examinees":211145,"passers":111241,"pass_rate":52.7,"source_url":"https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/pdf/statistics/202203_ip_shikenkekka.pdf","retrieved_at":"2026-07-26"}],"source_url":"https://www3.jitec.ipa.go.jp/JitesCbt/html/openinfo/pass.html","retrieved_at":"2026-07-26","notes":"IPAが公表する年度累計の試験結果PDFから取得した。年度は4月から翌年3月まで。全5年度について合格者数÷受験者数が公表合格率と小数第1位まで一致することを検算済み。合格者数は令和5年度以降3年連続で13万人台にあるが、令和3年度は111,241人・令和4年度は119,495人で、13万人台は直近3年の水準である。","unit_labels":{"applicants":"応募者数","examinees":"受験者数(実際に受験した人数)","passers":"合格者数","pass_rate":"合格率(%)"},"public_note":"IPAが公表している年度単位の全国集計です。「応募者」は申し込んだ人数、「受験者」は実際に受験した人数を指します。"}}')
ON CONFLICT DO NOTHING;

